const clubs=["f91-dudelange","fc-residence-walferdange","fc-atert-bissen"],clubData=new Map;async function loadClub(e){const a=await fetch(`squads/${e}.json`);if(!a.ok)throw new Error(`Could not load squads/${e}.json`);return await a.json()}function escapeHtml(e){return String(e).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;")}function renderClubRow(e){clubData.set(e.club,e);let a="";switch(e.status){case"OKAY":a='<span class="status pass">PASS</span>';break;case"UPDATED":a=`<span class="status fail" data-squad="${escapeHtml(e.club)}">FAIL</span>`;break;case"MIGRATION":a='<span class="status migration">MIGRATION</span>';break;default:a='<span class="status fail">ERROR</span>'}return`<tr><td>${escapeHtml(e.club)}</td><td>${a}</td></tr>`}function renderTable(e){const a=document.getElementById("content");clubData.clear();let t="";for(const a of e)a.error?t+=`<tr><td>${escapeHTML(a.club)}</td><td><span class="status fail">ERROR</span></td></tr>`:t+=renderClubRow(a.data);a.innerHTML=`<table><thead><tr><th>Club</th><th>Squad</th></tr></thead><tbody>${t}</tbody></table>`,document.querySelectorAll(".status.fail[data-squad]").forEach(e=>{e.addEventListener("click",()=>{const a=e.dataset.squad,t=clubData.get(a);t&&openSquadChanges(t)})})}function openSquadChanges(e){document.getElementById("modal-title").textContent=`${e.club} - Squad Changes`;let a="";if(e.newPlayers&&e.newPlayers.length>0){a+='<div class="change-section new"><h3>New players</h3><ul>';for(const t of e.newPlayers)a+=`<li>${escapeHtml(t.name)}</li>`;a+="</ul></div>"}if(e.departedPlayers&&e.departedPlayers.length>0){a+='<div class="change-section departed"><h3>Departed players</h3><ul>';for(const t of e.departedPlayers)a+=`<li>${escapeHtml(t.name)}</li>`;a+="</ul></div>"}if(e.changedPlayers&&e.changedPlayers.length>0){a+='<div class="change-section changed"><h3>Changed players</h3><ul>';for(const t of e.changedPlayers)a+=`<li><strong>${escapeHtml(t.name)}</strong><div class="change-detail">`,t.changes.position&&(a+=`<span>Position: ${escapeHtml(t.changes.position.old??"__")} > ${escapeHtml(t.changes.position.new??"__")}</span>`),t.changes.number&&(a+=`<span>Number: ${escapeHtml(t.changes.number.old??"__")} > ${escapeHtml(t.changes.number.new??"__")}</span>`),a+="</div></li>";a+="</ul></div>"}document.getElementById("modal-body").innerHTML=a,document.getElementById("modal-backdrop").classList.add("visible")}function closeModal(){document.getElementById("modal-backdrop").classList.remove("visible"),document.querySelector(".modal").classList.remove("modal-bounce")}async function loadAllClubs(){const e=[];for(const a of clubs){try{const t=await loadClub(a);e.push({club:a,data:t})}catch(t){e.push({club:a,error:t instanceof Error?t.message:String(t)})}renderTable(e)}}document.getElementById("close-modal").addEventListener("click",closeModal),document.getElementById("modal-backdrop").addEventListener("click",e=>{if(e.target===document.getElementById("modal-backdrop")){const e=document.querySelector(".modal");e.classList.remove("modal-bounce"),e.offsetWidth,e.classList.add("modal-bounce")}}),loadAllClubs();